                WITH said(slug, was, now) AS (VALUES
                    ('hilkiah-at-ezras-right-hand', $$A contemporary of Ezra, not the pre-exilic Hilkiah son of Shallum in Ezra's own genealogy. The encyclopedia's record merges the two, which is why its distinguisher names this verse while its own verse list does not.$$,
                     $$A contemporary of Ezra, not the pre-exilic Hilkiah son of Shallum in Ezra's own genealogy.$$),
